from typing import Optional, List

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """
    Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C
    """
    # Initial consistency check for the top-left corner
    if r[0] != c[0]:
        return None

    grid = [['.' for _ in range(n)] for _ in range(n)]

    # Initialize boundaries
    for i in range(n):
        grid[i][0] = r[i]
    for j in range(n):
        grid[0][j] = c[j]

    def get_row_counts(row_idx):
        counts = {'A': 0, 'B': 0, 'C': 0}
        for j in range(n):
            char = grid[row_idx][j]
            if char in counts:
                counts[char] += 1
        return counts

    def get_col_counts(col_idx):
        counts = {'A': 0, 'B': 0, 'C': 0}
        for i in range(n):
            char = grid[i][col_idx]
            if char in counts:
                counts[char] += 1
        return counts

    # Initial check for the first row and first column
    r0_counts = get_row_counts(0)
    if any(count > 1 for count in r0_counts.values()):
        return None
    c0_counts = get_col_counts(0)
    if any(count > 1 for count in c0_counts.values()):
        return None

    def solve(row, col):
        # Move to next row
        if col == n:
            return solve(row + 1, 0)

        # Base case: finished the grid
        if row == n:
            # Final validation: check if every row and col has exactly one A, B, C
            for i in range(n):
                if get_row_counts(i) != {'A': 1, 'B': 1, 'C': 1}:
                    return False
            for j in range(n):
                if get_col_counts(j) != {'A': 1, 'B': 1, 'C': 1}:
                    return False
            return True

        # Skip cells already filled by the initial r and c constraints
        if row == 0 or col == 0:
            return solve(row, col + 1)

        # Try placing 'A', 'B', 'C' or '.'
        # To prune: a cell can be A, B, or C only if it doesn't violate the 'exactly one' rule
        for char in ['A', 'B', 'C', '.']:
            if char != '.':
                # Check if char is already in this row or col
                if any(grid[row][j] == char for j in range(n)) or \n                   any(grid[i][col] == char for i in range(n)):
                    continue

            grid[row][col] = char
            # Heuristic: check if current row is now impossible (too many empty cells for needed chars)
            # Since N is small (up to 5), simple backtracking is usually sufficient.
            if solve(row, col + 1):
                return True
            grid[row][col] = '.'

        return False

    if solve(0, 0):
        return ["".join(row) for row in grid]
    return None

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside
    """
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell (top-to-bottom, left-to-right)
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        # Base case: no empty cells left, grid is fully tiled
        if r == -1:
            return True

        # Try placing each available tile at (r, c)
        for i in range(n):
            if not used[i]:
                used[i] = True
                # A tile can be placed as (th, tw) or (tw, th)
                # Using a set to avoid redundant checks if tile is square
                orientations = {tiles[i], (tiles[i][1], tiles[i][0])}
                for th, tw in orientations:
                    # Check if tile fits within boundaries starting from (r, c)
                    if r + th <= h and c + tw <= w:
                        # Check if all required cells are currently empty
                        possible = True
                        for rh in range(r, r + th):
                            for cw in range(c, c + tw):
                                if grid[rh][cw]:
                                    possible = False
                                    break
                            if not possible: break

                        if possible:
                            # Place the tile
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = True

                            # Recurse to fill the rest of the grid
                            if solve():
                                return True

                            # Backtrack: remove the tile
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = False
                used[i] = False
        return False

    return solve()

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def get_h(X, Y):
        if X <= 0 or Y <= 0: return 0
        qX4, rX4 = divmod(X, 4)
        qY2, rY2 = divmod(Y, 2)

        total_2area = qX4 * qY2 * 8

        def simple_2area(x, y):
            res = 0
            x1 = min(1.0, x)
            if x1 > 0:
                res += 2 * (x1 * y - 0.5 * max(0, x1 + y - 2)**2)
            x2_start = 1.0
            x2_end = min(2.0, x)
            if x2_end > x2_start:
                res += 2 * ((x2_end - 1) * y - (2*x2_end - 0.5*x2_end**2 - 1.5))
            return res

        def get_area_rect_v2(x_lim, y_lim):
            if x_lim <= 0 or y_lim <= 0: return 0
            area_0_2 = simple_2area(min(2.0, x_lim), y_lim)
            if x_lim > 2:
                area_2_4 = 2 * (x_lim - 2) * y_lim - simple_2area(x_lim - 2, y_lim)
                return area_0_2 + area_2_4
            return area_0_2

        return total_2area + get_area_rect_v2(rX4, rY2)

    shift_x = ((-A // 4) + 1) * 4
    shift_y = ((-B // 2) + 1) * 2

    A_s, C_s = A + shift_x, C + shift_x
    B_s, D_s = B + shift_y, D + shift_y

    return int(round(get_h(C_s, D_s) - get_h(A_s, D_s) - get_h(C_s, B_s) + get_h(A_s, B_s)))

from functools import lru_cache

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def solve(n_str):
        if not n_str or int(n_str) < 0:
            return 0

        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == len(n_str):
                # A number is beautiful if it has started, equal even/odd count, and is divisible by k
                return 1 if (is_started and diff == 0 and rem == 0) else 0

            res = 0
            limit = int(n_str[idx]) if not is_less else 9

            for digit in range(limit + 1):
                new_is_less = is_less or (digit < limit)
                if not is_started:
                    if digit == 0:
                        # Still haven't started the number (leading zeros)
                        res += dp(idx + 1, 0, 0, new_is_less, False)
                    else:
                        # First non-zero digit starts the number
                        new_diff = diff + (1 if digit % 2 == 0 else -1)
                        new_rem = (rem * 10 + digit) % k
                        res += dp(idx + 1, new_diff, new_rem, new_is_less, True)
                else:
                    # Number already started, all digits (including 0) count
                    new_diff = diff + (1 if digit % 2 == 0 else -1)
                    new_rem = (rem * 10 + digit) % k
                    res += dp(idx + 1, new_diff, new_rem, new_is_less, True)
            return res

        return dp(0, 0, 0, False, False)

    return solve(str(high)) - solve(str(low - 1))

from typing import Optional, List

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    # The grid is N x N. Each row and column must contain exactly one 'A', 'B', and 'C'.
    # All other cells must be '.'.
    # Constraint: grid[i][0] = r[i] and grid[0][j] = c[j].

    if r[0] != c[0]:
        return None

    grid = [['.' for _ in range(n)] for _ in range(n)]
    for i in range(n):
        grid[i][0] = r[i]
    for j in range(n):
        grid[0][j] = c[j]

    def is_valid(row, col, char):
        # Check row uniqueness
        for j in range(n):
            if j != col and grid[row][j] == char:
                return False
        # Check column uniqueness
        for i in range(n):
            if i != row and grid[i][col] == char:
                return False
        return True

    def backtrack(row, col):
        if row == n:
            # Final check: Each row and col must contain exactly 'A', 'B', 'C'
            for i in range(n):
                chars = [grid[i][j] for j in range(n) if grid[i][j] != '.']
                if sorted(chars) != ['A', 'B', 'C']:
                    return False
            for j in range(n):
                chars = [grid[i][j] for i in range(n) if grid[i][j] != '.']
                if sorted(chars) != ['A', 'B', 'C']:
                    return False
            return True

        next_row, next_col = (row, col + 1) if col < n - 1 else (row + 1, 0)

        if grid[row][col] != '.':
            # Fixed cell: check if it's valid in its current state
            if not is_valid(row, col, grid[row][col]):
                return False
            return backtrack(next_row, next_col)

        # Option 1: Try placing 'A', 'B', or 'C'
        for char in ['A', 'B', 'C']:
            if is_valid(row, col, char):
                grid[row][col] = char
                if backtrack(next_row, next_col):
                    return True
                grid[row][col] = '.'

        # Option 2: Leave it as '.'
        grid[row][col] = '.'
        if backtrack(next_row, next_col):
            return True

        return False

    if backtrack(0, 0):
        return ["".join(row) for row in grid]
    return None

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside
    """
    grid_area = h * w
    if sum(a * b for a, b in tiles) < grid_area:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell (top-to-bottom, left-to-right)
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1:
            return True

        for i in range(n):
            if not used[i]:
                used[i] = True
                # Try both orientations
                for th, tw in {tiles[i], (tiles[i][1], tiles[i][0])}:
                    if r + th <= h and c + tw <= w:
                        # Check if the rectangle can be placed
                        possible = True
                        for row in range(r, r + th):
                            for col in range(c, c + tw):
                                if grid[row][col]:
                                    possible = False
                                    break
                            if not possible: break

                        if possible:
                            # Place tile
                            for row in range(r, r + th):
                                for col in range(c, c + tw):
                                    grid[row][col] = True

                            if solve():
                                return True

                            # Backtrack
                            for row in range(r, r + th):
                                for col in range(c, c + tw):
                                    grid[row][col] = False
                used[i] = False
        return False

    return solve()

from functools import lru_cache

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def count_upto(n, k):
        if n <= 0:
            return 0
        s = str(n)
        L = len(s)

        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            # diff: count of even digits - count of odd digits
            if idx == L:
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            # Case 1: Leading zeros (still hasn't started)
            if not is_started:
                res += dp(idx + 1, 0, 0, True, False)

            # Case 2: Placing a digit
            limit = int(s[idx]) if not is_less else 9
            # If not started, the first digit must be at least 1 to avoid overlapping with leading zeros
            start = 1 if not is_started else 0

            for d in range(start, limit + 1):
                new_is_less = is_less or (d < limit)
                new_diff = diff + (1 if d % 2 == 0 else -1)
                new_rem = (rem * 10 + d) % k
                res += dp(idx + 1, new_diff, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    return count_upto(high, k) - count_upto(low - 1, k)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def count_upto(n: int, limit: int, s: str) -> int:
        if n < 0:
            return 0
        n_str = str(n)
        n_len = len(n_str)
        s_len = len(s)

        # If the suffix itself contains a digit > limit, no powerful integer exists
        if any(int(d) > limit for d in s):
            return 0

        total = 0
        # Count powerful integers with length L < n_len
        # L must be at least s_len
        for L in range(s_len, n_len):
            # A powerful integer of length L has a fixed suffix s.
            # It has a prefix of length P = L - s_len.
            P = L - s_len
            if P == 0:
                # Number is exactly s. Suffix s must be positive (no leading zero unless s='0')
                # The problem says s is a positive integer, so s[0] != '0'.
                if s[0] != '0':
                    total += 1
            else:
                # Prefix starts with digit 1..limit, remaining P-1 digits are 0..limit
                total += limit * ((limit + 1) ** (P - 1))

        # Count powerful integers with length exactly n_len
        if n_len >= s_len:
            P = n_len - s_len
            if P == 0:
                # Only candidate is s itself
                if s[0] != '0' and int(s) <= n:
                    total += 1
            else:
                # Prefix must be between 10^(P-1) and n_str[:P]
                # Prefix digits must be <= limit
                prefix_n_str = n_str[:P]

                # Count prefixes of length P with digits <= limit that are < prefix_n_str
                # and start with 1..limit
                count_less = 0
                for i in range(P):
                    digit_n = int(prefix_n_str[i])
                    start_digit = 1 if i == 0 else 0
                    for d in range(start_digit, min(digit_n, limit + 1)):
                        count_less += (limit + 1) ** (P - 1 - i)
                    if digit_n > limit:
                        break
                    if i == P - 1:
                        # We counted everything strictly less than prefix_n_str
                        pass

                total += count_less

                # Now consider the case where the prefix is exactly prefix_n_str
                if all(int(d) <= limit for d in prefix_n_str) and prefix_n_str[0] != '0':
                    # Check if the full number (prefix_n_str + s) is <= n
                    if int(prefix_n_str + s) <= n:
                        total += 1

        return total

    return count_upto(finish, limit, s) - count_upto(start - 1, limit, s)

from typing import Optional, List

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    grid = [['.' for _ in range(n)] for _ in range(n)]

    def check_final(grid):
        for i in range(n):
            row_chars = [grid[i][j] for j in range(n) if grid[i][j] != '.']
            if len(row_chars) != 3 or sorted(row_chars) != ['A', 'B', 'C']:
                return False
            if not row_chars or row_chars[0] != r[i]:
                return False
        for j in range(n):
            col_chars = [grid[i][j] for i in range(n) if grid[i][j] != '.']
            if len(col_chars) != 3 or sorted(col_chars) != ['A', 'B', 'C']:
                return False
            if not col_chars or col_chars[0] != c[j]:
                return False
        return True

    def solve_recursive(row, col):
        if row == n:
            return check_final(grid)

        nc = col + 1
        nr = row
        if nc == n:
            nr = row + 1
            nc = 0

        for char in ['A', 'B', 'C', '.']:
            if char != '.':
                # Pruning: Row/Col uniqueness
                if any(grid[row][j] == char for j in range(col)):
                    continue
                if any(grid[i][col] == char for i in range(row)):
                    continue

                # Row leftmost constraint pruning
                # If this is the first non-'.' in the row, it must be r[row]
                is_first_in_row = True
                for j in range(col):
                    if grid[row][j] != '.':
                        is_first_in_row = False
                        break
                if is_first_in_row and char != r[row]:
                    continue

                # Col topmost constraint pruning
                # If this is the first non-'.' in the col, it must be c[col]
                is_first_in_col = True
                for i in range(row):
                    if grid[i][col] != '.':
                        is_first_in_col = False
                        break
                if is_first_in_col and char != c[col]:
                    continue
            else:
                # Pruning: If we are at the end of a row and no characters were placed, 
                # or if we can't fit 3 characters in the remaining cells.
                if col == n - 1:
                    row_count = sum(1 for j in range(n-1) if grid[row][j] != '.')
                    if row_count != 3:
                        # We can't skip the last cell if we need it, or if we already have 3
                        # Actually, easier to check total row count at the end of row.
                        pass

            grid[row][col] = char
            # Quick check: if we finished a row, must have exactly 3 chars and start with r[row]
            if col == n - 1:
                row_chars = [grid[row][j] for j in range(n) if grid[row][j] != '.']
                if len(row_chars) != 3 or sorted(row_chars) != ['A', 'B', 'C'] or row_chars[0] != r[row]:
                    grid[row][col] = '.'
                    continue

            if solve_recursive(nr, nc):
                return True
            grid[row][col] = '.'
        return False

    if solve_recursive(0, 0):
        return ["".join(row) for row in grid]
    return None

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    # Initialize the grid as a 2D list of Booleans (False = empty)
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell (top-to-bottom, left-to-right)
        row, col = -1, -1
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    row, col = r, c
                    break
            if row != -1: break

        # If no empty cell is found, the grid is perfectly tiled
        if row == -1:
            return True

        # Try placing each available tile
        for i in range(n):
            if not used[i]:
                # Try both orientations (a x b and b x a)
                a, b = tiles[i]
                # Use a set to avoid redundant checks if a == b
                orientations = {(a, b), (b, a)}
                for rh, rw in orientations:
                    # Check if tile fits starting at (row, col)
                    # The tile must cover (row, col), so it must start at or before (row, col)
                    # Since we always pick the FIRST empty cell, the tile MUST start at (row, col)
                    # in terms of the top-leftmost cell it occupies.
                    if row + rh <= h and col + rw <= w:
                        possible = True
                        for r in range(row, row + rh):
                            for c in range(col, col + rw):
                                if grid[r][c]:
                                    possible = False
                                    break
                            if not possible: break

                        if possible:
                            # Place the tile
                            for r in range(row, row + rh):
                                for c in range(col, col + rw):
                                    grid[r][c] = True
                            used[i] = True

                            if solve():
                                return True

                            # Backtrack
                            used[i] = False
                            for r in range(row, row + rh):
                                for c in range(col, col + rw):
                                    grid[r][c] = False
        return False

    # Basic area check: total available area must be at least the grid area
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    return solve()

from functools import lru_cache

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def solve(n_str, k):
        # dp(index, diff, rem, is_less, is_started)
        # diff = count_even - count_odd
        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == len(n_str):
                return 1 if (is_started and diff == 0 and rem == 0) else 0

            res = 0
            limit = int(n_str[idx]) if not is_less else 9

            for digit in range(limit + 1):
                new_is_less = is_less or (digit < limit)
                new_is_started = is_started or (digit > 0)

                if not new_is_started:
                    # Still leading zeros
                    res += dp(idx + 1, 0, 0, new_is_less, False)
                else:
                    # Digit is part of the number
                    new_diff = diff + (1 if digit % 2 == 0 else -1)
                    new_rem = (rem * 10 + digit) % k
                    res += dp(idx + 1, new_diff, new_rem, new_is_less, True)
            return res

        return dp(0, 0, 0, False, False)

    # Range [low, high] is solve(high) - solve(low - 1)
    # Using strings for the digit DP
    res_high = solve(str(high), k)
    res_low = solve(str(low - 1), k)
    return res_high - res_low

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def count_upto(n: int, limit: int, s: str) -> int:
        if n <= 0:
            return 0

        n_str = str(n)
        n_len = len(n_str)
        s_len = len(s)

        # If suffix contains a digit > limit, no powerful integer can exist
        if any(int(digit) > limit for digit in s):
            return 0

        # Range of lengths: the number must have at least s_len digits
        # and at most n_len digits to be <= n.
        total = 0

        for L in range(s_len, n_len + 1):
            # Case 1: Length is smaller than n_len
            if L < n_len:
                if L == s_len:
                    # Only one possible number: the suffix itself
                    # Suffix cannot start with '0' unless it's just "0",
                    # but the problem says s represents a positive integer.
                    if s[0] != '0':
                        total += 1
                else:
                    # First digit: 1 to limit (limit choices)
                    # Middle digits: 0 to limit (limit + 1 choices)
                    # Suffix is fixed.
                    # Number of positions before suffix: L - s_len
                    # First position is special: [1, limit]
                    # Other positions: [0, limit]
                    total += limit * ((limit + 1) ** (L - s_len - 1))

            # Case 2: Length is exactly n_len
            else:
                # We need to count numbers X = Prefix + Suffix where X <= n
                # and Prefix has length L - s_len, all digits <= limit.
                prefix_len = L - s_len
                if prefix_len == 0:
                    # X is just the suffix
                    if s[0] != '0' and int(s) <= n:
                        total += 1
                else:
                    # Digit DP for prefix
                    n_prefix = n_str[:prefix_len]
                    n_suffix = n_str[prefix_len:]

                    memo = {}
                    def dp(idx, is_less, is_started):
                        state = (idx, is_less, is_started)
                        if state in memo: return memo[state]

                        if idx == prefix_len:
                            # We reached the end of the prefix. 
                            # If the prefix is exactly n_prefix, we must ensure s <= n_suffix.
                            if not is_less:
                                return 1 if s <= n_suffix else 0
                            return 1

                        res = 0
                        upper = int(n_prefix[idx]) if not is_less else 9
                        # Digits allowed: 0 to min(upper, limit)
                        for d in range(min(upper, limit) + 1):
                            # First digit of the prefix cannot be 0
                            if not is_started and d == 0:
                                continue

                            res += dp(idx + 1, is_less or (d < upper), True)

                        memo[state] = res
                        return res

                    total += dp(0, False, False)

        return total

    return count_upto(finish, limit, s) - count_upto(start - 1, limit, s)

