def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    grid = [['.' for _ in range(n)] for _ in range(n)]

    def is_valid(row, col, char):
        # Each row and column contains exactly one 'A', one 'B', and one 'C'
        # Since we are placing and checking, we only need to ensure no duplicates
        # of the character we are about to place.
        for j in range(n):
            if grid[row][j] == char:
                return False
        for i in range(n):
            if grid[i][col] == char:
                return False
        return True

    def backtrack(cell_idx):
        if cell_idx == n * n:
            # Final verification: every row and col must have exactly one A, B, C
            for row in range(n):
                row_chars = [grid[row][j] for j in range(n) if grid[row][j] != '.']
                if sorted(row_chars) != ['A', 'B', 'C']:
                    return False
            for col in range(n):
                col_chars = [grid[i][col] for i in range(n) if grid[i][col] != '.']
                if sorted(col_chars) != ['A', 'B', 'C']:
                    return False
            return True

        row = cell_idx // n
        col = cell_idx % n

        # Try 'A', 'B', 'C', and '.'
        # To optimize, we only try characters and '.'
        for char in ['A', 'B', 'C', '.']:
            if char != '.':
                # Constraint: leftmost character written in i-th row matches r[i]
                # Leftmost written means the first non-'.' in the row.
                is_first_in_row = all(grid[row][k] == '.' for k in range(col))
                if is_first_in_row and char != r[row]:
                    continue
                # If it's not the first, we must ensure we haven't already violated the first char rule
                # (which we haven't, because we proceed cell by cell).

                # Constraint: topmost character written in i-th column matches c[i]
                is_first_in_col = all(grid[k][col] == '.' for k in range(row))
                if is_first_in_col and char != c[col]:
                    continue

                if not is_valid(row, col, char):
                    continue
            else:
                # If we place a '.', we must ensure that we can still place the required chars
                # This is implicitly handled by the final verification, but we can skip
                # if we've already filled too many '.' in a row/col.
                pass

            grid[row][col] = char
            if backtrack(cell_idx + 1):
                return True
            grid[row][col] = '.'

        return False

    if backtrack(0):
        return ["".join(row) for row in grid]
    return None

