def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside
    """
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell (top-to-bottom, left-to-right)
        r, c = -1, -1
        for row in range(h):
            for col in range(w):
                if not grid[row][col]:
                    r, c = row, col
                    break
            if r != -1: break

        # If no empty cell is found, the grid is fully tiled
        if r == -1:
            return True

        for i in range(n):
            if not used[i]:
                used[i] = True
                # Try both rotations of the tile
                # Use a set to avoid duplicate attempts if the tile is square
                rotations = {tiles[i], (tiles[i][1], tiles[i][0])}
                for th, tw in rotations:
                    # Check if tile fits within bounds and doesn't overlap starting from (r, c)
                    if r + th <= h and c + tw <= w:
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[r + dr][c + dc]:
                                    possible = False
                                    break
                            if not possible: break

                        if possible:
                            # Place the tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = True

                            if solve():
                                return True

                            # Backtrack
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = False
                used[i] = False
        return False

    # Basic pruning: Total area of all available tiles must be at least grid area
    if sum(a * b for a, b in tiles) < h * w:
        return False

    return solve()

