def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def solve(n_str):
        @lru_cache(None)
        def dp(idx, balance, rem, is_less, is_started):
            if idx == len(n_str):
                return 1 if (is_started and balance == 0 and rem == 0) else 0

            res = 0
            # Leading zeros handling: if not started, we can keep not starting
            if not is_started:
                res += dp(idx + 1, 0, 0, True, False)

            limit = int(n_str[idx]) if not is_less else 9

            # If we start now, we must pick a digit >= 1 if we are at the first digit
            # But wait, the leading zeros logic above handles the 'not started' state.
            # When starting the number, we can pick any digit from 0 to limit, 
            # but if we are still at the very first digit, it must be 1-9 to 'start'.
            # However, simpler is: if is_started is False, and we pick d=0, we stay not started.
            # If we pick d > 0, we become started.

            start_digit = 0
            for d in range(start_digit, limit + 1):
                if not is_started and d == 0:
                    # This is already handled by the 'res += dp(idx + 1, 0, 0, True, False)'
                    # so we skip it here to avoid double counting.
                    continue

                new_is_less = is_less or (d < limit)
                new_balance = balance + (1 if d % 2 == 0 else -1)
                new_rem = (rem * 10 + d) % k
                res += dp(idx + 1, new_balance, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    return solve(str(high)) - solve(str(low - 1))

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def count_upto(N, limit, s):
        if N <= 0:
            return 0

        s_val = int(s)
        if N < s_val:
            return 0

        # Suffix must be valid according to the limit
        if any(int(d) > limit for d in s):
            return 0

        # The problem states s represents a positive integer, 
        # meaning it shouldn't have leading zeros unless s is "0".
        # However, since s is a suffix, the total number x just needs to end with it.
        # The only constraint is that x is a positive integer.

        s_len = len(s)
        N_str = str(N)
        L = len(N_str)

        total = 0
        # Count numbers with length len_val from s_len to L
        for len_val in range(s_len, L + 1):
            if len_val < L:
                # All numbers of length len_val are < N
                if len_val == s_len:
                    # Only the number s itself
                    # s must not have leading zeros to be considered a 'positive integer' of length s_len
                    if s[0] != '0':
                        total += 1
                else:
                    # First digit: 1..limit (limit choices)
                    # Middle digits: 0..limit ((limit + 1)^(len_val - s_len - 1) choices)
                    # Suffix: fixed
                    total += limit * ((limit + 1) ** (len_val - s_len - 1))
            else:
                # len_val == L
                # Use Digit DP for numbers of length exactly L that are <= N
                memo = {}
                def dp_L(idx, is_less):
                    state = (idx, is_less)
                    if state in memo: return memo[state]
                    if idx == L:
                        return 1

                    res = 0
                    upper = int(N_str[idx]) if not is_less else 9

                    if idx >= L - s_len:
                        # We are in the suffix part
                        digit = int(s[idx - (L - s_len)])
                        if digit <= limit and digit <= upper:
                            res += dp_L(idx + 1, is_less or (digit < upper))
                    else:
                        # We are in the prefix part
                        lower = 1 if idx == 0 else 0
                        for d in range(lower, min(limit, upper) + 1):
                            res += dp_L(idx + 1, is_less or (d < upper))

                    memo[state] = res
                    return res

                # Only count if the first digit of the number of length L is not zero
                total += dp_L(0, False)

        return total

    return count_upto(finish, limit, s) - count_upto(start - 1, limit, s)

