def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    grid = [['.' for _ in range(n)] for _ in range(n)]

    # Leftmost character of i-th row is r[i] -> grid[i][0] = r[i]
    # Topmost character of i-th column is c[i] -> grid[0][i] = c[i]
    # The corner cell grid[0][0] must satisfy both constraints.
    if r[0] != c[0]:
        return None

    for i in range(n):
        grid[i][0] = r[i]
        grid[0][i] = c[i]

    def is_valid(row, col, char):
        # Check row uniqueness for 'A', 'B', 'C'
        for j in range(n):
            if grid[row][j] == char:
                return False
        # Check col uniqueness for 'A', 'B', 'C'
        for i in range(n):
            if grid[i][col] == char:
                return False
        return True

    def solve(row, col):
        if row == n:
            # Final verification: every row and col must have exactly one 'A', 'B', 'C'
            for i in range(n):
                row_chars = [grid[i][j] for j in range(n) if grid[i][j] != '.']
                if sorted(row_chars) != ['A', 'B', 'C']:
                    return False
            for j in range(n):
                col_chars = [grid[i][j] for i in range(n) if grid[i][j] != '.']
                if sorted(col_chars) != ['A', 'B', 'C']:
                    return False
            return True

        next_row, next_col = (row, col + 1) if col < n - 1 else (row + 1, 0)

        if grid[row][col] != '.':
            return solve(next_row, next_col)

        # Try placing 'A', 'B', or 'C'
        for char in ['A', 'B', 'C']:
            if is_valid(row, col, char):
                grid[row][col] = char
                if solve(next_row, next_col):
                    return True
                grid[row][col] = '.'

        # Try leaving it empty
        if solve(next_row, next_col):
            return True

        return False

    # Preliminary check for fixed cells to ensure they don't violate the uniqueness constraint
    for i in range(n):
        row_vals = [grid[i][j] for j in range(n) if grid[i][j] != '.']
        if len(row_vals) != len(set(row_vals)):
            return None
    for j in range(n):
        col_vals = [grid[i][j] for i in range(n) if grid[i][j] != '.']
        if len(col_vals) != len(set(col_vals)):
            return None

    if solve(0, 0):
        return [''.join(row) for row in grid]

    return None

