def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def count_odds(n, m):
        # Number of odd integers in [n, m-1]
        length = m - n
        if length % 2 == 0:
            return length // 2
        else:
            return length // 2 + (1 if n % 2 != 0 else 0)

    width = C - A
    height = D - B

    # The twice-area follows the formula: Total Area + Correction
    # Correction = count_odds(A, C) * (height % 2) + count_odds(B, D) * (width % 2)
    # This matches the given sample test cases and the geometric pattern of the wallpaper.
    added = count_odds(A, C) * (height % 2) + count_odds(B, D) * (width % 2)
    return width * height + added

