def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """
    Calculate twice the area of black-painted regions inside a rectangle on AtCoder's wallpaper pattern.
    The pattern is periodic and balanced. Analysis of the sample cases suggests the formula
    f(X, Y) = X*Y + (X % 2) * (Y % 2) represents 2 * Area([0, X] x [0, Y])
    and the final area is obtained via the inclusion-exclusion principle.
    """
    def f(X, Y):
        # Use Python's % operator which handles negative numbers correctly for this periodicity
        return X * Y + (X % 2) * (Y % 2)

    return f(C, D) - f(A, D) - f(C, B) + f(A, B)

def count_ways_to_stair(k: int) -> int:
    import math

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        if r > n // 2:
            r = n - r

        num = 1
        for i in range(r):
            num = num * (n - i) // (i + 1)
        return num

    total_ways = 0
    # k can be up to 10^9, 2^30 is ~1.07*10^9. 
    # We check n from 0 up to 31 to cover the possible range where 2^n - k <= n + 1.
    for n in range(32):
        d = (1 << n) - k
        if 0 <= d <= n + 1:
            total_ways += nCr(n + 1, d)

    return total_ways

