                if row_chars.count('A') != 1 or row_chars.count('B') != 1 or row_chars.count('C') != 1:
                    return False
            for j in range(n):
                col_chars = [grid[i][j] for i in range(n)]
                if col_chars.count('A') != 1 or col_chars.count('B') != 1 or col_chars.count('C') != 1:
                    return False
            return True

        next_row, next_col = (row, col + 1) if col < n - 1 else (row + 1, 0)

        # Case 1: Current cell is fixed by R (leftmost) or C (topmost)
        fixed_char = None
        if col == 0:
            fixed_char = r[row]
        elif row == 0:
            fixed_char = c[col]

        if fixed_char:
            # If it's fixed, check if it violates uniqueness
            # Note: The problem says the character AT that position is fixed.
            # If row=0 and col=0, both R[0] and C[0] must be the same.
            if col == 0 and row == 0 and r[0] != c[0]:
                return False

            # Temporarily set to check if it's valid in its row/col
            # Actually, the rules are: "Each row and column contains exactly one A, B, C".
            # Since we are placing it, we just need to check if this character already exists in the row/col.
            # But wait, the cell (0,0) is the first for both R and C. 
            # Let's just try placing the fixed_char.
            char = fixed_char
            # We need to be careful with is_valid because it checks the whole grid.
            # Since we are filling sequentially, we only check existing entries.
            valid = True
            for j in range(col):
                if grid[row][j] == char: valid = False
            for i in range(row):
                if grid[i][col] == char: valid = False

            if valid:
                grid[row][col] = char
                if solve(next_row, next_col):
                    return True
                grid[row][col] = '.'
            return False
        else:
            # Case 2: Cell is not fixed, try 'A', 'B', 'C', or '.'
            for char in ['A', 'B', 'C', '.']:
                valid = True
                if char != '.':
                    for j in range(col):
                        if grid[row][j] == char: valid = False
                    for i in range(row):
                        if grid[i][col] == char: valid = False

                if valid:
                    grid[row][col] = char
                    if solve(next_row, next_col):
                        return True
                    grid[row][col] = '.'
            return False

    if solve(0, 0):
        return ["".join(row) for row in grid]
    return None

