def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def solve(n_str):
        n_len = len(n_str)

        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == n_len:
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            limit = int(n_str[idx]) if not is_less else 9

            for d in range(limit + 1):
                new_is_less = is_less or (d < limit)
                new_is_started = is_started or (d > 0)

                if not new_is_started:
                    # Still processing leading zeros
                    res += dp(idx + 1, 0, 0, new_is_less, False)
                else:
                    # Actual number digits
                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    new_rem = (rem * 10 + d) % k
                    res += dp(idx + 1, new_diff, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    return solve(str(high)) - solve(str(low - 1))

from typing import Optional, List

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    grid = [['.' for _ in range(n)] for _ in range(n)]

    # Initial constraints
    # Row i's leftmost char must be R[i]
    # Col j's topmost char must be C[j]
    for i in range(n):
        grid[i][0] = r[i]
    for j in range(n):
        grid[0][j] = c[j]

    # Check if the top-left corner is consistent
    if r[0] != c[0]:
        return None

    def is_valid(row, col, char):
        # Check row constraints: no duplicate A, B, or C
        for j in range(n):
            if j != col and grid[row][j] == char:
                return False
        # Check column constraints: no duplicate A, B, or C
        for i in range(n):
            if i != row and grid[i][col] == char:
                return False
        return True

    def solve(row, col):
        if row == n:
            # Final verification: ensure every row/col has exactly one A, B, and C
            for i in range(n):
                row_vals = grid[i]
                if row_vals.count('A') != 1 or row_vals.count('B') != 1 or row_vals.count('C') != 1:
                    return False
            for j in range(n):
                col_vals = [grid[i][j] for i in range(n)]
                if col_vals.count('A') != 1 or col_vals.count('B') != 1 or col_vals.count('C') != 1:
                    return False
            return True

        next_row, next_col = (row, col + 1) if col < n - 1 else (row + 1, 0)

        # If cell is pre-filled (first row or first col)
        if row == 0 or col == 0:
            # We just need to check if the pre-filled cell is already valid
            # However, pre-filling might have already happened. 
            # Just validate current state and move on.
            char = grid[row][col]
            if char == '.':
                # This shouldn't happen based on initialization
                return False
            # We must ensure the pre-filled value doesn't violate uniqueness
            # within its row/col among existing entries.
            # For simplicity, we validate the whole grid at the end or check as we go.
            # Let's check current pre-fill uniqueness:
            for j in range(n):
                if j != col and grid[row][j] != '.' and grid[row][j] == char:
                    return False
            for i in range(n):
                if i != row and grid[i][col] != '.' and grid[i][col] == char:
                    return False
            return solve(next_row, next_col)

        # Try filling the cell with A, B, C, or '.'
        for char in ['A', 'B', 'C', '.']:
            if char == '.':
                grid[row][col] = '.'
                if solve(next_row, next_col):
                    return True
            else:
                if is_valid(row, col, char):
                    grid[row][col] = char
                    if solve(next_row, next_col):
                        return True

        grid[row][col] = '.' # backtrack
        return False

    # Pre-validate first row and col uniqueness
    for i in range(n):
        if r.count(r[i]) > 1: # Not strictly forbidden, but each row must have exactly one A, B, C
            # This logic is flawed because R specifies only the LEFTMOST char
            # Wait, "Each row and column contains exactly one 'A', one 'B', and one 'C'"
            # This means if R = 'AAA', then the 0th col has three 'A's, which is forbidden.
            pass

    # The first col is R, the first row is C. 
    # Check if R contains more than one A, B, or C
    # Actually, the constraints are: 1. Each row contains exactly one A, B, C. 
    # 2. Each col contains exactly one A, B, C. 
    # 3. grid[i][0] == R[i], grid[0][j] == C[j].

    # Therefore, R cannot have duplicate A, B, or C if N=3.
    # But if N=4, R could be 'AABC', and the first column would have two 'A's, which is NOT allowed.
    # Thus, R and C MUST contain exactly one A, one B, and one C if they are to be valid
    # as the first column and first row respectively.
    # Wait, the prompt says "Each row and column contains exactly one 'A', one 'B', and one 'C'".
    # That means regardless of N, only 3 cells are filled with A, B, C, and N-3 are '.'.

    if r.count('A') > 1 or r.count('B') > 1 or r.count('C') > 1 or \
       c.count('A') > 1 or c.count('B') > 1 or c.count('C') > 1:
        return None

    if solve(0, 0):
        return ["".join(row) for row in grid]
    else:
        return None

