def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def count_upto(n_str, k):
        L = len(n_str)

        @functools.lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == L:
                return 1 if (is_started and diff == 0 and rem == 0) else 0

            res = 0
            limit = int(n_str[idx]) if not is_less else 9

            for d in range(limit + 1):
                new_is_less = is_less or (d < limit)
                new_is_started = is_started or (d > 0)

                if not new_is_started:
                    # Still leading zeros
                    res += dp(idx + 1, 0, 0, new_is_less, False)
                else:
                    # Number has started
                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    new_rem = (rem * 10 + d) % k
                    res += dp(idx + 1, new_diff, new_rem, new_is_less, True)
            return res

        return dp(0, 0, 0, False, False)

    count_high = count_upto(str(high), k)
    count_low = count_upto(str(low - 1), k)
    return count_high - count_low

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def count_upto(n_str, limit, s):
        if not n_str:
            return 0

        n_len = len(n_str)
        s_len = len(s)

        # Suffix must be valid under limit
        for digit in s:
            if int(digit) > limit:
                return 0

        # If the target number is shorter than the suffix, no positive integer can satisfy this
        if n_len < s_len:
            return 0

        def solve(idx, is_less, is_started):
            # We only need to determine digits before the suffix
            if idx == n_len - s_len:
                # Check if the suffix itself is within the bound given the current prefix
                if is_less:
                    return 1
                else:
                    # Compare the suffix of n_str with s
                    suffix_n = n_str[n_len - s_len:]
                    if s <= suffix_n:
                        return 1
                    else:
                        return 0

            # Memoization for this part could be added, but state is small
            # Since we are only iterating through prefixes, we can use simple loops
            return 0

        # Instead of full DP, we can use a combinatorial approach for prefixes
        # Prefix length: pref_len = n_len - s_len
        pref_len = n_len - s_len

        # Case 1: Numbers with length < n_len
        total = 0
        for length in range(s_len, n_len):
            # The number is 'prefix' + 's'
            # Prefix length is length - s_len
            p_len = length - s_len
            if p_len == 0:
                # Just the suffix s. Check if s is a positive integer
                if int(s) > 0:
                    total += 1
            else:
                # First digit of prefix: 1 to limit
                # Other digits: 0 to limit
                # Only if the number is positive. Suffix s is a positive integer string.
                # The first digit cannot be 0.
                first_digit_options = limit - 1 + 1 # 1..limit is 'limit' options
                # Wait, if the number starts with the suffix (p_len=0), it's already covered
                # If p_len > 0, the first digit of the whole number is the first digit of the prefix
                total += limit * ((limit + 1) ** (p_len - 1))

        # Case 2: Numbers with length == n_len
        # Prefix must be <= n_str[:pref_len]
        # Prefix cannot have leading zero unless pref_len == 0
        prefix_limit = n_str[:pref_len]

        def count_prefixes(limit_str, limit_val):
            # Count numbers of length len(limit_str) that are <= limit_str and digits <= limit_val
            # First digit cannot be 0 unless limit_str is "0"
            if not limit_str:
                return 1

            count = 0
            l_len = len(limit_str)
            for i in range(l_len):
                digit_bound = int(limit_str[i])
                # Try digits smaller than digit_bound
                for d in range(0, digit_bound):
                    if i == 0 and d == 0 and l_len > 0: continue
                    if d <= limit_val:
                        count += (limit_val + 1) ** (l_len - 1 - i)

                # Try digit equal to digit_bound
                if digit_bound > limit_val:
                    break
                if i == l_len - 1:
                    count += 1
            return count

        if pref_len == 0:
            # Only the suffix. Check if it's within [1, n]
            if 1 <= int(s) <= int(n_str):
                total += 1
        else:
            # Use combinatorial count for prefix <= n_str[:pref_len]
            # But if the prefix is exactly n_str[:pref_len], the suffix s must be <= n_str[pref_len:]

            # Count prefixes strictly less than prefix_limit
            # To do this, we find the first index where the prefix must be smaller
            p_count = 0
            for i in range(pref_len):
                digit_bound = int(prefix_limit[i])
                for d in range(0, digit_bound):
                    if i == 0 and d == 0: continue
                    if d <= limit:
                        p_count += (limit + 1) ** (pref_len - 1 - i)
                if digit_bound > limit:
                    break
                if i == pref_len - 1:
                    # This means the prefix could be exactly prefix_limit
                    # Now check the suffix
                    if s <= n_str[pref_len:]:
                        p_count += 1
            total += p_count

        return total

    return count_upto(str(finish), limit, s) - count_upto(str(start - 1), limit, s)

