        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        # All cells covered
        if r == -1:
            return True

        # Try placing each unused tile
        for i in range(n):
            if not used[i]:
                # A tile (a, b) can be placed as a x b or b x a
                tile_dims = [tiles[i], (tiles[i][1], tiles[i][0])]
                # Avoid redundant check if tile is square
                if tiles[i][0] == tiles[i][1]:
                    tile_dims = [tiles[i]]

                for dr, dc in tile_dims:
                    # Check if tile fits at (r, c) as the top-left cell
                    if r + dr <= h and c + dc <= w:
                        # Check if all cells it would cover are empty
                        possible = True
                        for rr in range(r, r + dr):
                            for cc in range(c, c + dc):
                                if grid[rr][cc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            # Place the tile
                            for rr in range(r, r + dr):
                                for cc in range(c, c + dc):
                                    grid[rr][cc] = True
                            used[i] = True

                            if solve():
                                return True

                            # Backtrack
                            used[i] = False
                            for rr in range(r, r + dr):
                                for cc in range(c, c + dc):
                                    grid[rr][cc] = False
        return False

    return solve()

