import math

def kth_smallest_amount(coins: List[int], k: int) -> int:
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0: return 0
        return abs(a * b) // gcd(a, b)

    # Precompute LCMs for all subsets to speed up count function
    n = len(coins)
    subsets_lcm = []
    for i in range(1, 1 << n):
        current_lcm = 1
        bits = 0
        for j in range(n):
            if (i >> j) & 1:
                current_lcm = lcm(current_lcm, coins[j])
                bits += 1
        subsets_lcm.append((current_lcm, bits))

    def count_multiples(x):
        count = 0
        for l, bits in subsets_lcm:
            if bits % 2 == 1:
                count += x // l
            else:
                count -= x // l
        return count

    # Binary search for the k-th smallest amount
    low = 1
    high = min(coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_multiples(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans
